import { NextResponse } from "next/server";
import { SESSION_COOKIE, safeEqual, sessionValue } from "@/lib/auth";

export async function POST(req: Request) {
  const form = await req.formData();
  const password = process.env.DASHBOARD_PASSWORD || "";
  const given = String(form.get("password") || "");
  const next = String(form.get("next") || "/");
  const target = new URL(next.startsWith("/") && !next.startsWith("//") ? next : "/", req.url);

  if (!password || !safeEqual(given, password)) {
    const back = new URL("/login", req.url);
    back.searchParams.set("error", "1");
    back.searchParams.set("next", target.pathname);
    return NextResponse.redirect(back, 303);
  }
  const res = NextResponse.redirect(target, 303);
  res.cookies.set(SESSION_COOKIE, await sessionValue(password), {
    httpOnly: true,
    secure: true,
    sameSite: "lax",
    path: "/",
    maxAge: 60 * 60 * 24 * 90,
  });
  return res;
}
export default async function Login({ searchParams }: PageProps<"/login">) {
  const { next, error } = await searchParams;
  return (
    <main className="page login">
      <form className="card" method="post" action="/api/login">
        <h1>SOLAR<span className="h1-accent">{"//GRID"}</span></h1>
        <label>
          <span className="label">Password</span>
          <input type="password" name="password" autoFocus required autoComplete="current-password" />
        </label>
        <input type="hidden" name="next" value={typeof next === "string" ? next : "/"} />
        {error && <p className="error">That password didn’t match.</p>}
        <button className="button" type="submit">Open dashboard</button>
      </form>
    </main>
  );
}
